'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isObject = require( '@stdlib/assert/is-object' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var discreteUniform = require( '@stdlib/random/base/discrete-uniform' );
var pkg = require( './../package.json' ).name;
var mannWhitneyU = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var result;
	var x;
	var y;
	var i;

	x = [];
	y = [];
	for ( i = 0; i < 100; i++ ) {
		x.push( 0 );
		y.push( 0 );
	}

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		fillArray( x );
		fillArray( y );
		result = mannWhitneyU( x, y );
		if ( typeof result !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isObject( result ) ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+'::one-sided', function benchmark( b ) {
	var result;
	var opts;
	var x;
	var y;
	var i;

	opts = {
		'alternative': 'greater'
	};
	x = [];
	y = [];
	for ( i = 0; i < 100; i++ ) {
		x.push( 0 );
		y.push( 0 );
	}

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		fillArray( x );
		fillArray( y );
		result = mannWhitneyU( x, y, opts );
		if ( typeof result !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isObject( result ) ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':print', function benchmark( b ) {
	var digits;
	var result;
	var output;
	var i;

	result = mannWhitneyU( [ 7, 8, 9 ], [ 1, 2, 3 ] );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		digits = ( i % 8 ) + 1;
		output = result.print({
			'digits': digits
		});
		if ( typeof output !== 'string' ) {
			b.fail( 'should return a string' );
		}
	}
	b.toc();
	if ( !isString( output ) ) {
		b.fail( 'should return a string' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});


// FUNCTIONS //

function fillArray( arr ) {
	var i;
	for ( i = 0; i < arr.length; i++ ) {
		arr[ i ] = discreteUniform( 0, 100 );
	}
}
